// The only node you edit. Any retailer works, but the ones on the Actor's
// supported list return the most complete fields.
const WATCH = [
  'https://www.amazon.com/dp/REPLACE_ME',
  'https://www.nordstrom.com/s/REPLACE_ME',
];
const SLACK_CHANNEL = '#pricing-alerts';

return [{ json: { detailsUrls: WATCH.map((url) => ({ url })), slackChannel: SLACK_CHANNEL } }];

// Field names, types and nesting differ per retailer, so reading them naively
// works on one store and breaks on the next.
//   price     number on some retailers, string on others
//   currency  offers.priceCurrency on some, offers.currency on others
//   stock     under additionalProperties, or only in offers.availability
//   brand     often carries marketing text such as 'Visit the Sony Store'
// Stock keeps three states: true, false, and null for unknown. Never map
// unknown to false.

const num = (v) => {
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  if (typeof v !== 'string') return null;
  const n = Number.parseFloat(v.replace(/[^\d.]/g, ''));
  return Number.isFinite(n) && n > 0 ? n : null;
};

const readStock = (item) => {
  const extras = item.additionalProperties || {};
  if (typeof extras.inStock === 'boolean') return extras.inStock;
  if (typeof item.inStock === 'boolean') return item.inStock;
  const avail = String((item.offers && item.offers.availability) || item.availability || '').toLowerCase();
  if (avail.includes('instock')) return true;
  if (avail.includes('outofstock')) return false;
  return null;
};

const readBrand = (item) => {
  const raw = String((item.brand && (item.brand.name || item.brand.slogan)) || item.brand || '').trim();
  const unwrapped = raw.replace(/^Visit the (.+) Store$/i, '$1');
  if (!unwrapped || unwrapped.length > 40 || unwrapped.split(/\s+/).length > 4) return null;
  return unwrapped;
};

const rows = [];
for (const entry of $input.all()) {
  const item = entry.json || {};
  const offers = item.offers || {};
  const extras = item.additionalProperties || {};
  const url = item.url || item.inputUrl || '';
  const price = num(offers.price);

  // An unresolvable URL returns an item with every field empty rather than an
  // error, so drop those instead of writing blank rows.
  if (!url || (!price && !item.name)) continue;

  let retailer = '';
  const host = String(url).match(/^https?:\/\/([^/?#]+)/);
  if (host) retailer = host[1].replace(/^www\./, '');

  rows.push({
    sku_key: url,
    product_url: url,
    retailer,
    product_name: String(item.name || item.title || '').replace(/opens in a new (window or )?tab$/i, '').trim() || null,
    brand: readBrand(item),
    price,
    currency: offers.priceCurrency || offers.currency || extras.currencyRaw || null,
    in_stock: readStock(item),
    image_url: Array.isArray(item.image) ? (item.image[0] || null) : (item.image || null),
    raw: item,
  });
}

// One item carrying the whole batch, so the insert below is a single round trip.
return [{ json: { rows, watched: rows.length } }];

// Fold every flagged product into one item, so the agent reasons once per run
// rather than once per product.
const moved = $input.all().map((i) => i.json);
return [{ json: { count: moved.length, moved: JSON.stringify(moved, null, 1) } }];
